    if not date:
        return False

    # Check if the date is in the format mm-dd-yyyy
    try:
        month, day, year = map(int, date.split('-'))
    except ValueError:
        return False

    # Validate the month
    if month < 1 or month > 12:
        return False

    # Validate the day based on the month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    elif month == 2:
